WorkspaceMember.sdl:
type WorkspaceMember {
  user: User!
  role: Role!
  joinedAt: DateTime!
}

Priority.sdl:
enum Priority {
  LOW
  MEDIUM
  HIGH
  URGENT
}

Tag.sdl:
type Tag implements Node {
  id: ID!
  name: String!
  color: String
}

TaskPage.sdl:
type TaskPage {
  items: [Task!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

PageInfo.sdl:
type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

PageInput.sdl:
input PageInput {
  first: Int = 20
  after: String
}

AddCommentInput.sdl:
input AddCommentInput {
  taskId: ID!
  body: String!
  parentId: ID
}
